'use strict';
const {test}=require('node:test');const assert=require('node:assert/strict');
const {evaluateFreshness,publicStatus,healthForRefresh,parseDate}=require('./freshness');
const now=Date.parse('2026-11-12T12:00:00Z');
const f=(p={})=>evaluateFreshness({snapshotCreatedAt:'2026-11-12T11:00:00Z',priceUpdatedAt:'2026-11-10T10:00:00Z',now,...p});
test('recent snapshot',()=>assert.equal(f().snapshot.status,'recent'));
test('old snapshot flagged',()=>assert.equal(f({snapshotCreatedAt:'2026-11-10T11:00:00Z'}).snapshot.status,'update_delayed'));
test('old price unchanged not invalid',()=>{const a=f({priceUpdatedAt:'2026-10-01T00:00:00Z'});assert.equal(a.price.status,'unchanged_for_a_while');assert.equal(a.priceValidity,'not_determined_by_age');assert.equal(a.hideStation,false)});
test('missing price date does not hide',()=>{const a=f({priceUpdatedAt:null});assert.equal(a.price.status,'unknown');assert.equal(a.hideStation,false)});
test('missing snapshot date',()=>assert.equal(f({snapshotCreatedAt:null}).snapshot.status,'unknown'));
test('future snapshot timestamp',()=>assert.equal(f({snapshotCreatedAt:'2026-11-13T12:00:00Z'}).snapshot.status,'future_timestamp'));
test('future price timestamp',()=>assert.equal(f({priceUpdatedAt:'2026-11-13T12:00:00Z'}).price.status,'future_timestamp'));
test('small clock drift tolerated',()=>assert.equal(f({priceUpdatedAt:'2026-11-12T12:04:00Z'}).price.status,'recent_change'));
test('negative age clamps zero',()=>assert.equal(f({priceUpdatedAt:'2026-11-12T12:01:00Z'}).price.ageMs,0));
test('invalid date returns null',()=>assert.equal(parseDate('yesterday'),null));
test('numeric timestamp not accepted',()=>assert.equal(parseDate(1234),null));
test('invalid config rejected',()=>assert.throws(()=>f({snapshotWarningAfterMs:-1}),/invalid_freshness_config/));
test('invalid now rejected',()=>assert.throws(()=>f({now:NaN}),/invalid_freshness_config/));
test('snapshot threshold boundary',()=>assert.equal(f({snapshotCreatedAt:'2026-11-11T12:00:00Z'}).snapshot.status,'recent'));
test('price threshold boundary',()=>assert.equal(f({priceUpdatedAt:'2026-11-05T12:00:00Z'}).price.status,'recent_change'));
test('delayed snapshot visible notice',()=>assert.equal(publicStatus(f({snapshotCreatedAt:'2026-11-09T12:00:00Z'})).showNotice,true));
test('unchanged price relegated to info',()=>assert.equal(publicStatus(f({priceUpdatedAt:'2026-10-01T12:00:00Z'})).infoOnly,true));
test('unknown price date relegated to info',()=>assert.equal(publicStatus(f({priceUpdatedAt:null})).infoOnly,true));
test('invalid metadata rejected',()=>assert.throws(()=>publicStatus(null),/invalid_freshness_metadata/));
test('health no success requires attention',()=>assert.equal(healthForRefresh({now}).status,'needs_attention'));
test('health recent success ok',()=>assert.equal(healthForRefresh({now,lastSuccessAt:now-1000}).status,'ok'));
test('health error after success retry',()=>assert.equal(healthForRefresh({now,lastSuccessAt:now-1000,lastErrorAt:now-100}).status,'retry_needed'));
test('health old success attention',()=>assert.equal(healthForRefresh({now,lastSuccessAt:now-90000000}).status,'needs_attention'));
test('health keeps last valid',()=>assert.equal(healthForRefresh({now}).serveLastValidSnapshot,true));
test('health invalid threshold',()=>assert.throws(()=>healthForRefresh({now,warnAfterMs:-1}),/invalid_health_config/));
